<script lang="ts">
  import * as Dialog from '$lib/components/ui/dialog';
  import { onMount } from 'svelte';
  import { Button } from '$lib/components/ui/button';
  import { Input } from '$lib/components/ui/input';
  import { Label } from '$lib/components/ui/label';
  import { ShieldCheck, KeyRound, Smartphone, LoaderCircle, Copy, RefreshCw } from '@lucide/svelte';
  import { request } from './api';
  import { createPasskey } from './webauthn';
  import SessionManager from './SessionManager.svelte';
  import OAuthButtons from './OAuthButtons.svelte';
  interface Key {id:string;name:string;created_at:string}
  interface State {totp_available:boolean;totp_enabled:boolean;passkeys:Key[];recovery_codes_remaining:number;mfa_required:boolean}
  let pendingRemoval=$state<string|null>(null);let confirmDisable=$state(false);
  const passkeysSupported=$state(typeof window!=='undefined'&&!!window.PublicKeyCredential&&window.isSecureContext);
  function downloadRecovery(){const blob=new Blob(['VideoFlow recovery codes\nEach code can be used once. Store this file securely.\n\n'+recoveryCodes.join('\n')],{type:'text/plain'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download='videoflow-recovery-codes.txt';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice='Recovery codes downloaded. Store them somewhere private.';}
  let securityState=$state<State|null>(null);let loading=$state(true);let busy=$state(false);let error=$state('');let notice=$state('');let password=$state('');let code=$state('');let setup=$state<{secret:string;otpauth_url:string}|null>(null);let setupCode=$state('');let qr=$state('');let recoveryCodes=$state<string[]>([]);let keyName=$state('');
  onMount(()=>{void load();});
  async function load(){loading=true;try{securityState=await request('/security');}catch(e){error=(e as Error).message;}finally{loading=false;}}
  async function action(work:()=>Promise<void>){busy=true;error='';notice='';try{await work();password='';code='';}catch(e){error=(e as Error).message;}finally{busy=false;}}
  function credentials(){return {password,...(code.trim()?{code:code.trim()}:{})};}
  async function begin(){await action(async()=>{setup=await request('/security/totp/begin',credentials());recoveryCodes=[];if(setup){const url=setup.otpauth_url;const module=await import('qrcode');qr=await module.toDataURL(url,{width:220,margin:3});}});}
  async function confirm(){await action(async()=>{const result=await request('/security/totp/confirm',{code:setupCode.trim()});recoveryCodes=result.recovery_codes||[];setup=null;setupCode='';qr='';await load();notice='Authenticator verification is enabled. Other sessions were signed out. Save your recovery codes now.';});}
  async function disable(){await action(async()=>{await request('/security/totp/disable',credentials());setup=null;recoveryCodes=[];await load();notice='Authenticator verification has been disabled. Other sessions were signed out.';});}
  async function addPasskey(){await action(async()=>{const begin=await request('/security/passkeys/register/options',credentials());const credential=await createPasskey(begin.options);await request('/security/passkeys/register/verify',{challenge:begin.challenge,credential,name:keyName.trim()||'My passkey'});keyName='';await load();notice='Your passkey was added. Keep another sign-in method available for recovery.';});}
  async function remove(id:string){await action(async()=>{await request(`/security/passkeys/${encodeURIComponent(id)}`,credentials(),'DELETE');await load();notice='The passkey was removed.';});}
  async function copy(value:string){try{await navigator.clipboard.writeText(value);notice='Copied. Store it somewhere private.';}catch{error='Copy was unavailable. Select the text and copy it manually.';}}
</script>
<div class="security-page">
  <div class="page-heading"><h1>Security</h1><p>Choose how you sign in and keep a recovery method available.</p></div>
  {#if error}<div class="cloud-alert" role="alert">{error}</div>{/if}{#if notice}<div class="cloud-notice" role="status">{notice}</div>{/if}
  {#if loading}<div class="cloud-loading" role="status"><LoaderCircle class="size-5 animate-spin"/>Loading security settings…</div>{:else if !securityState}<Button onclick={load}>Try again</Button>{:else}
    <div class="security-summary" role="status"><ShieldCheck class="size-5"/><div><strong>{securityState.totp_enabled||securityState.passkeys.length?"Extra sign-in protection is enabled":"Add an extra layer of protection"}</strong><p>{securityState.passkeys.length} passkey{securityState.passkeys.length===1?"":"s"} · Authenticator {securityState.totp_enabled?"enabled":"not set up"}{securityState.totp_enabled?` · ${securityState.recovery_codes_remaining} recovery codes remaining`:""}</p></div></div><section class="security-section"><div class="security-heading"><ShieldCheck class="size-5"/><div><h2>Confirm it’s you</h2><p>Changes to your sign-in methods require your current password{securityState.totp_enabled?' and either a fresh authenticator code or a recent passkey sign-in':''}.</p></div></div><div class="security-fields"><div><Label for="security-password">Current password</Label><Input id="security-password" type="password" bind:value={password} autocomplete="current-password" disabled={busy}/></div>{#if securityState.totp_enabled}<div><Label for="security-code">Fresh authenticator code</Label><Input id="security-code" bind:value={code} autocomplete="one-time-code" inputmode="numeric" maxlength={6} disabled={busy}/></div>{/if}</div>{#if securityState.passkeys?.length}<p class="security-help">Adding or removing a passkey also requires a recent sign-in with an existing passkey. <a href="/login?returnTo=%2Fsecurity">Verify with your passkey</a>, then return here.</p>{/if}</section>
    <section class="security-section"><div class="security-heading"><Smartphone class="size-5"/><div><h2>Authenticator app</h2><p>{securityState.totp_enabled?'Enabled. Password sign-in asks for a code from your authenticator or an unused recovery code.':'Use a time-based code as an extra check after your password.'}</p></div></div>
      {#if !securityState.totp_available}<p class="security-help">New authenticator setup is unavailable right now. Existing verification stays in place.</p>{:else if !setup}<div class="security-actions">{#if !securityState.totp_enabled}<Button disabled={busy||!password} onclick={begin}>{#if busy}<LoaderCircle class="size-4 animate-spin"/>{/if}Set up authenticator</Button>{:else}<Button variant="outline" disabled={busy||!password||(!securityState.passkeys.length&&!code)} onclick={()=>confirmDisable=true}>Disable authenticator</Button>{/if}</div>{/if}
      {#if setup}<div class="authenticator-setup"><div>{#if qr}<img src={qr} width="220" height="220" alt="Local QR code to add VideoFlow to your authenticator app"/>{/if}</div><div><ol class="setup-steps" aria-label="Authenticator setup"><li class="complete">Confirm your identity</li><li aria-current="step">Scan the QR code</li><li>Verify your code</li><li>Save recovery codes</li></ol><h3>Add VideoFlow to your app</h3><p>Scan this QR code in your authenticator app, or enter the setup key manually. Keep the key private.</p><div class="security-secret"><code>{setup.secret}</code><Button variant="ghost" size="icon-sm" aria-label="Copy authenticator setup key" onclick={()=>copy(setup!.secret)}><Copy class="size-4"/></Button></div><form onsubmit={(event)=>{event.preventDefault();void confirm();}}><Label for="setup-totp-code">Code from your authenticator</Label><Input id="setup-totp-code" bind:value={setupCode} inputmode="numeric" pattern={'[0-9]{6}'} maxlength={6} autocomplete="one-time-code" required disabled={busy}/><div class="security-actions"><Button type="submit" disabled={busy||setupCode.length!==6}>Verify and enable</Button><Button type="button" variant="ghost" disabled={busy} onclick={()=>{setup=null;qr='';setupCode='';}}>Cancel setup</Button></div></form></div></div>{/if}
      {#if recoveryCodes.length}<div class="recovery-codes" role="status"><h3>Save your recovery codes</h3><p>Each code works once. These codes are shown only now. Store them somewhere private before leaving this page.</p><div class="recovery-grid">{#each recoveryCodes as recovery}<code>{recovery}</code>{/each}</div><div class="security-actions"><Button variant="outline" onclick={()=>copy(recoveryCodes.join('\n'))}><Copy class="size-4"/>Copy recovery codes</Button><Button variant="outline" onclick={downloadRecovery}>Download codes</Button><Button variant="ghost" onclick={()=>recoveryCodes=[]}>I saved my codes</Button></div></div>{:else if securityState.totp_enabled}<p class="security-help">{securityState.recovery_codes_remaining} recovery codes remaining. To switch authenticator apps, disable this one and set up another. New setup replaces the recovery codes.</p>{/if}
    </section>
    <section class="security-section"><div class="security-heading"><KeyRound class="size-5"/><div><h2>Passkeys</h2><p>Use your device’s fingerprint, face verification, PIN or security key. VideoFlow never receives your private key.</p></div></div><p class="security-help">Once a passkey is added, password sign-in also needs an enrolled second factor. Keep another passkey or an authenticator with saved recovery codes so you can recover access.</p>
      <ol class="passkey-guide"><li>Confirm your identity above.</li><li>Name this device, then select Add a passkey.</li><li>Follow your browser’s device or security key instructions.</li></ol>{#if !passkeysSupported}<p class="security-help" role="status">Passkeys need a supported browser and a secure HTTPS connection. Try a current browser or use your authenticator.</p>{/if}<div class="passkey-list">{#each securityState.passkeys||[] as key}<div class="passkey-row"><KeyRound class="size-4"/><div><strong>{key.name||'Passkey'}</strong><small>Added {new Date(key.created_at).toLocaleDateString()}</small></div><Button variant="outline" size="sm" disabled={busy||!password||(securityState.totp_enabled&&!securityState.passkeys.length&&!code)} onclick={()=>pendingRemoval=key.id}>Remove</Button></div>{:else}<p class="security-help">No passkeys added yet.</p>{/each}</div><Label for="passkey-name">Passkey name</Label><Input id="passkey-name" bind:value={keyName} maxlength={80} placeholder="For example, personal laptop" disabled={busy}/><div class="security-actions"><Button disabled={busy||!passkeysSupported||!password||(securityState.totp_enabled&&!securityState.passkeys.length&&!code)} onclick={addPasskey}>{#if busy}<LoaderCircle class="size-4 animate-spin"/>{:else}<KeyRound class="size-4"/>{/if}Add a passkey</Button><Button variant="ghost" disabled={busy} onclick={load}><RefreshCw class="size-4"/>Refresh settings</Button></div>
    </section>
    <section class="security-section"><div class="security-heading"><KeyRound class="size-5"/><div><h2>Connected sign-in providers</h2><p>Link a provider after confirming your identity. Your extra sign-in protection still applies.</p></div></div><OAuthButtons link {password} {code}/></section>
    <SessionManager/>
  {/if}
</div>
<Dialog.Root bind:open={confirmDisable}><Dialog.Content><Dialog.Header><Dialog.Title>Disable authenticator?</Dialog.Title><Dialog.Description>You will no longer be asked for codes from this app. Existing recovery codes will stop working and other sessions will be signed out.</Dialog.Description></Dialog.Header><Dialog.Footer><Button variant="outline" onclick={()=>confirmDisable=false}>Keep authenticator</Button><Button disabled={busy} onclick={async()=>{await disable();confirmDisable=false;}}>Disable authenticator</Button></Dialog.Footer></Dialog.Content></Dialog.Root>
<Dialog.Root open={pendingRemoval!==null} onOpenChange={open=>{if(!open)pendingRemoval=null;}}><Dialog.Content><Dialog.Header><Dialog.Title>Remove this passkey?</Dialog.Title><Dialog.Description>This device or security key will no longer sign you in. Make sure you have another sign-in method before removing it.</Dialog.Description></Dialog.Header><Dialog.Footer><Button variant="outline" onclick={()=>pendingRemoval=null}>Keep passkey</Button><Button disabled={busy} onclick={async()=>{if(pendingRemoval)await remove(pendingRemoval);pendingRemoval=null;}}>Remove passkey</Button></Dialog.Footer></Dialog.Content></Dialog.Root>
<style>
.security-summary{display:flex;align-items:flex-start;gap:12px;padding:20px 0 26px}.security-summary strong{font-size:14px}.security-summary p{font-size:12px;color:var(--muted-foreground);margin:7px 0 0;line-height:1.7}.setup-steps,.passkey-guide{padding-left:20px;color:var(--muted-foreground);font-size:13px;line-height:1.8;margin:0 0 20px}.setup-steps [aria-current]{font-weight:600;color:var(--foreground)}.security-page{max-width:760px;margin-inline:auto}.security-section{padding:30px 0;border-top:1px solid var(--border)}.security-heading{display:flex;align-items:flex-start;gap:14px;margin-bottom:20px}.security-heading>:global(svg){flex-shrink:0;margin-top:4px}.security-heading h2{font-size:18px;font-weight:600;margin:0 0 7px}.security-heading p,.security-help,.authenticator-setup p,.recovery-codes p{font-size:13px;color:var(--muted-foreground);line-height:1.75}.security-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.security-fields>div{display:grid;gap:10px}.security-help{margin:14px 0}.security-help a{color:var(--foreground);text-decoration:underline;text-underline-offset:4px}.security-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.authenticator-setup{display:grid;grid-template-columns:220px minmax(0,1fr);gap:24px;margin-top:25px}.authenticator-setup img{background:white;border-radius:12px;max-width:100%}.authenticator-setup h3,.recovery-codes h3{font-size:15px;font-weight:600;margin:0 0 10px}.security-secret{display:flex;gap:8px;align-items:center;margin:16px 0;border:1px solid var(--border);padding:10px;border-radius:8px}.security-secret code{flex:1;min-width:0;overflow-wrap:anywhere;font-size:12px;user-select:all}.authenticator-setup form{display:grid;gap:10px}.recovery-codes{border:1px solid var(--border);border-radius:12px;padding:20px;margin-top:24px}.recovery-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:18px}.recovery-grid code{font-size:13px;overflow-wrap:anywhere;user-select:all}.passkey-list{margin:22px 0}.passkey-row{display:flex;align-items:center;gap:12px;padding:16px 0;border-bottom:1px solid var(--border)}.passkey-row>div{flex:1;min-width:0}.passkey-row strong{display:block;font-size:13px;overflow-wrap:anywhere}.passkey-row small{display:block;font-size:12px;color:var(--muted-foreground);margin-top:5px}@media(max-width:650px){.security-fields,.authenticator-setup{grid-template-columns:1fr}.authenticator-setup>div:first-child{margin:auto}.security-section{padding-block:24px}.recovery-grid{grid-template-columns:1fr}}
</style>
